// Reclamos del lote: CSV con comillas y comas en el texto. Se quita el BOM y se ordena por ingreso.
const p = $('CA85aP_Parametros').first().json;
const n = new Date(), z = (x) => String(x).padStart(2, '0');
const prefijo = `PRUEBA-${n.getFullYear()}${z(n.getMonth() + 1)}${z(n.getDate())}${z(n.getHours())}${z(n.getMinutes())}${z(n.getSeconds())}-`;
let txt = String($input.first().json.data || '').replace(/^﻿/, '');
const filas = []; let fila = [], campo = '', comillas = false;
for (let i = 0; i < txt.length; i++) {
  const ch = txt[i];
  if (comillas) {
    if (ch === '"' && txt[i + 1] === '"') { campo += '"'; i++; }
    else if (ch === '"') comillas = false;
    else campo += ch;
  } else if (ch === '"') comillas = true;
  else if (ch === ',') { fila.push(campo); campo = ''; }
  else if (ch === '\n' || ch === '\r') { if (ch === '\r' && txt[i + 1] === '\n') i++; fila.push(campo); filas.push(fila); fila = []; campo = ''; }
  else campo += ch;
}
if (campo !== '' || fila.length) { fila.push(campo); filas.push(fila); }
const cab = filas.shift().map((c) => c.trim());
let correos = filas.filter((f) => f.length === cab.length).map((f) => Object.fromEntries(cab.map((c, k) => [c, f[k]])));
correos.sort((a, b) => a.fecha_hora_ingreso.localeCompare(b.fecha_hora_ingreso) || a.reclamo_id.localeCompare(b.reclamo_id));
if (p.limite > 0) correos = correos.slice(0, p.limite);
return correos.map((c) => ({ json: { ...c, prefijo_id: prefijo } }));

const c = $('CA85aP_Por_reclamo').first().json;
const r = $input.first().json;
return [{ json: { reclamo_id: c.reclamo_id, estado: r.error ? 'error' : r.estado, categoria: r.categoria || null, urgencia: r.urgencia || null,
  cliente_identificado: r.cliente_identificado === true, sospechoso: r.sospechoso === true, pedido_datos_personales: r.pedido_datos_personales === true,
  enmascarado: !!r.texto_enmascarado, error: r.error ? (r.error.message || String(r.error)) : null } }];

// Compara con la categoría correcta del lote (valores copiados de datos/verdad: los flujos nunca leen esa carpeta).
